int f1(int a[], int value) {
   int r_value = -1;
   int i = 0;
   while (i < 100) {
      if (a[i] == value) {
         r_value = i;
         break;
      }
      i = i + 1;
   }
   return r_value;
}

// f2
int f2(int a[], int value) {
   int r_value = -1;
   int low = 0, high = 99;
   int mid;
   while (low <= high) {
      mid = (low + high)/2;
      if (a[mid] == value) {
         r_value = mid;
         break;
      }
      else if (a[mid] < value) {
         low = mid + 1;
      }
      else {
         high = mid - 1;
      }
   }
   return r_value;
}

int f (int n) {
   int sum=0;
   if (n<2) {
      return 0;
   }
   for (int i=1; i<=n; i=i+1) {
      sum = sum + i;
   }
   sum = sum + f(2*n/3);
   return sum;
}

